import{_ as a,c as s,o as t,a3 as r}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Orders and payments","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/orders-payments/index.md","filePath":"master/sales/point-of-sale/orders-payments/index.md","lastUpdated":1791902625000}'),o={name:"master/sales/point-of-sale/orders-payments/index.md"};function n(i,e,l,d,h,p){return t(),s("div",null,e[0]||(e[0]=[r('<h1 id="orders-and-payments" tabindex="-1">Orders and payments <a class="header-anchor" href="#orders-and-payments" aria-label="Permalink to &quot;Orders and payments&quot;">​</a></h1><p>Every sale you ring up at the till becomes an order in the back office. Each payment taken on that order is saved too. This group shows you where to find them, check them and follow them to invoices and refunds.</p><blockquote><p><strong>In simple words:</strong> The till is where you sell. The Orders menu is where you look back at what was sold and who paid.</p></blockquote><h2 id="how-the-pieces-connect" tabindex="-1">How the pieces connect <a class="header-anchor" href="#how-the-pieces-connect" aria-label="Permalink to &quot;How the pieces connect&quot;">​</a></h2><ol><li>A cashier opens a register and starts a session. See <a href="./../sessions/open-register.html">Open a register</a>.</li><li>The cashier sells products. Each sale creates one order, for example <strong>TNE/00001</strong>.</li><li>The cashier takes payment. Each payment method used creates a payment line on the order.</li><li>The order moves through its states: <strong>New</strong>, <strong>Paid</strong>, <strong>Posted</strong>, <strong>Invoiced</strong> or <strong>Cancelled</strong>.</li><li>You review orders and payments in the admin app under <code>Point of Sale → Orders</code>.</li></ol><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><ul><li><a href="./orders.html">Orders</a>: the list of all POS orders, the order page, and the actions you can run on an order.</li><li><a href="./payments.html">Payments</a>: every payment line, grouped by method or session.</li><li><a href="./customers.html">Customers</a>: the people you attach to orders.</li></ul><p>The <code>Orders</code> menu also holds <strong>Sessions</strong> and <strong>Preparation Printers</strong>. Read about them in <a href="./../sessions/">Sessions</a> and <a href="./../payments-setup/preparation-printers.html">Preparation printers</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Start with the <strong>Orders</strong> page. It is the quickest way to answer &quot;what did we sell today and was it paid?&quot;.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../selling/take-an-order.html">Take an order</a></li><li><a href="./../selling/refunds.html">Refunds</a></li><li><a href="./../selling/invoice-a-pos-order.html">Invoice a POS order</a></li></ul>',11)]))}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
